const { fonte, janela } = $json;
const versaoApi = 'v23.0';
const base = `https://graph.facebook.com/${versaoApi}`;
const conta = encodeURIComponent(String(fonte.externalId));
const timeRange = encodeURIComponent(JSON.stringify({ since: janela.start, until: janela.end }));
const comuns = `time_increment=1&time_range=${timeRange}&use_unified_attribution_setting=true&limit=500`;

const camposDoAnuncio = [
  'campaign_id', 'campaign_name', 'adset_id', 'ad_id', 'date_start', 'account_currency',
  'spend', 'impressions', 'reach', 'frequency', 'clicks', 'inline_link_clicks', 'inline_post_engagement',
  'unique_clicks', 'unique_inline_link_clicks', 'outbound_clicks',
  'video_play_actions', 'video_30_sec_watched_actions', 'video_p25_watched_actions', 'video_p50_watched_actions',
  'video_p75_watched_actions', 'video_p95_watched_actions', 'video_p100_watched_actions',
  'video_thruplay_watched_actions', 'video_avg_time_watched_actions',
  'quality_ranking', 'engagement_rate_ranking', 'conversion_rate_ranking',
  'actions', 'action_values', 'cost_per_action_type', 'conversions', 'conversion_values', 'cost_per_conversion',
].join(',');

const camposDoRecorte = [
  'campaign_id', 'adset_id', 'date_start', 'account_currency',
  'spend', 'impressions', 'reach', 'clicks', 'inline_link_clicks', 'actions', 'action_values',
].join(',');

const camposDaCampanha = [
  'id', 'name', 'objective', 'status', 'effective_status', 'buying_type', 'bid_strategy', 'daily_budget',
  'lifetime_budget', 'spend_cap', 'special_ad_categories', 'start_time', 'stop_time', 'created_time',
].join(',');

const camposDoConjunto = [
  'id', 'name', 'campaign_id', 'status', 'effective_status', 'optimization_goal', 'billing_event', 'bid_strategy',
  'bid_amount', 'daily_budget', 'lifetime_budget', 'destination_type', 'attribution_spec', 'promoted_object',
  'start_time', 'end_time', 'created_time',
].join(',');

const camposDoAnuncioEntidade = [
  'id', 'name', 'campaign_id', 'adset_id', 'status', 'effective_status', 'creative{id}', 'created_time',
].join(',');

const statusDaCampanha = ['ACTIVE', 'PAUSED', 'ARCHIVED', 'IN_PROCESS', 'WITH_ISSUES'];
const statusDoConjunto = [...statusDaCampanha, 'CAMPAIGN_PAUSED'];
const statusDoAnuncio = [...statusDoConjunto, 'ADSET_PAUSED', 'DISAPPROVED', 'PENDING_REVIEW', 'PENDING_BILLING_INFO', 'PREAPPROVED'];

function entidade(borda, campos, status) {
  return `${base}/${conta}/${borda}?fields=${encodeURIComponent(campos)}&effective_status=${encodeURIComponent(JSON.stringify(status))}&limit=200`;
}

function relatorio(chave, nivel, campos, recorte) {
  const breakdowns = recorte ? `&breakdowns=${recorte}` : '';
  return { chave, url: `${base}/${conta}/insights?level=${nivel}&fields=${encodeURIComponent(campos)}${breakdowns}&${comuns}` };
}

return [{
  json: {
    inicio: Date.now(),
    versaoApi,
    fonte,
    janela,
    base,
    conta,
    urls: {
      campanhas: entidade('campaigns', camposDaCampanha, statusDaCampanha),
      conjuntos: entidade('adsets', camposDoConjunto, statusDoConjunto),
      anuncios: entidade('ads', camposDoAnuncioEntidade, statusDoAnuncio),
    },
    relatorios: [
      relatorio('anuncio', 'ad', camposDoAnuncio, null),
      relatorio('idade_genero', 'adset', camposDoRecorte, 'age,gender'),
      relatorio('posicionamento', 'adset', camposDoRecorte, 'publisher_platform,platform_position'),
      relatorio('regiao', 'adset', camposDoRecorte, 'region'),
    ],
  },
}];

const contexto = $('Montar requisição').first().json;
const respostas = $input.all().map((item) => item.json);

function removerToken(texto) {
  return String(texto).replace(/access_token=[^&\s"']+/g, 'access_token=[removido]');
}

function classificar(resposta) {
  if (!resposta) return { causa: 'api_recusou', detalhe: 'a Meta não respondeu' };
  if (resposta.error) {
    const detalhe = resposta.error?.message ?? String(resposta.error);
    return { causa: 'api_recusou', detalhe: removerToken(`falha de rede: ${detalhe}`).slice(0, 500) };
  }
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = Array.isArray(resposta.body) ? resposta.body[0]?.error : resposta.body?.error;
  const codigo = erro?.code;
  const detalhe = removerToken(String(erro?.message || `HTTP ${resposta.statusCode}`)).slice(0, 500);
  const limiteDeUso = resposta.statusCode === 429 || [4, 17, 32, 341, 613].includes(codigo) || (codigo >= 80000 && codigo <= 80014)
    || /SERVICE_DISABLED|accessNotConfigured|RESOURCE_EXHAUSTED|RATE_LIMIT|request limit|reduce the amount of data/i.test(JSON.stringify(erro ?? {}));
  const semAcesso = !limiteDeUso && (resposta.statusCode === 401 || resposta.statusCode === 403 || [190, 10, 200].includes(codigo));
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

const relatorios = contexto.relatorios.map((especificacao, indice) => {
  const resposta = respostas[indice];
  const falha = classificar(resposta);
  const runId = resposta?.body?.report_run_id;
  if (falha || !runId) {
    const motivo = falha ?? { causa: 'api_recusou', detalhe: 'a Meta não devolveu o id do relatório assíncrono' };
    return { chave: especificacao.chave, runId: null, estado: 'falhou', causa: motivo.causa, detalhe: motivo.detalhe };
  }
  return { chave: especificacao.chave, runId: String(runId), estado: 'pendente', causa: null, detalhe: null };
});

return [{ json: { relatorios } }];

const contexto = $('Montar requisição').first().json;
const estado = $runIndex === 0
  ? $('Registrar relatórios').first().json.relatorios
  : $('Avaliar relatórios').all(0, $runIndex - 1)[0].json.relatorios;
const neutra = `${contexto.base}/${contexto.conta}?fields=id`;

return estado.map((relatorio) => ({
  json: {
    ...relatorio,
    consultaUrl: relatorio.estado === 'pendente'
      ? `${contexto.base}/${relatorio.runId}?fields=id,async_status,async_percent_completion`
      : neutra,
  },
}));

const MAXIMO_DE_TENTATIVAS = 30;
const consultados = $('Montar consulta').all(0, $runIndex).map((item) => item.json);
const respostas = $input.all().map((item) => item.json);

function removerToken(texto) {
  return String(texto).replace(/access_token=[^&\s"']+/g, 'access_token=[removido]');
}

function classificar(resposta) {
  if (!resposta) return { causa: 'api_recusou', detalhe: 'a Meta não respondeu' };
  if (resposta.error) {
    const detalhe = resposta.error?.message ?? String(resposta.error);
    return { causa: 'api_recusou', detalhe: removerToken(`falha de rede: ${detalhe}`).slice(0, 500) };
  }
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = Array.isArray(resposta.body) ? resposta.body[0]?.error : resposta.body?.error;
  const codigo = erro?.code;
  const detalhe = removerToken(String(erro?.message || `HTTP ${resposta.statusCode}`)).slice(0, 500);
  const limiteDeUso = resposta.statusCode === 429 || [4, 17, 32, 341, 613].includes(codigo) || (codigo >= 80000 && codigo <= 80014)
    || /SERVICE_DISABLED|accessNotConfigured|RESOURCE_EXHAUSTED|RATE_LIMIT|request limit|reduce the amount of data/i.test(JSON.stringify(erro ?? {}));
  const semAcesso = !limiteDeUso && (resposta.statusCode === 401 || resposta.statusCode === 403 || [190, 10, 200].includes(codigo));
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

const tentativa = $runIndex + 1;
const esgotou = tentativa >= MAXIMO_DE_TENTATIVAS;

const relatorios = consultados.map((relatorio, indice) => {
  const { consultaUrl, ...atual } = relatorio;
  if (atual.estado !== 'pendente') return atual;
  const resposta = respostas[indice];
  const falha = classificar(resposta);
  if (falha) return { ...atual, estado: 'falhou', causa: falha.causa, detalhe: falha.detalhe };
  const situacao = resposta.body?.async_status;
  if (situacao === 'Job Completed') return { ...atual, estado: 'concluido' };
  if (situacao === 'Job Failed' || situacao === 'Job Skipped') {
    return { ...atual, estado: 'falhou', causa: 'api_recusou', detalhe: `relatório assíncrono: ${situacao}` };
  }
  if (esgotou) {
    return { ...atual, estado: 'falhou', causa: 'api_recusou', detalhe: 'relatório assíncrono não terminou a tempo' };
  }
  return atual;
});

return [{ json: { relatorios, tentativa, terminou: relatorios.every((relatorio) => relatorio.estado !== 'pendente') } }];

const contexto = $('Montar requisição').first().json;
const { relatorios, tentativa } = $input.first().json;
const neutra = `${contexto.base}/${contexto.conta}?fields=id`;

const urls = {};
for (const relatorio of relatorios) {
  urls[relatorio.chave] = relatorio.estado === 'concluido'
    ? `${contexto.base}/${relatorio.runId}/insights?limit=500`
    : neutra;
}

return [{ json: { relatorios, tentativa, urls } }];

const contexto = $('Montar requisição').first().json;
const preparo = $('Preparar downloads').first().json;
const estados = Object.fromEntries(preparo.relatorios.map((relatorio) => [relatorio.chave, relatorio]));
const JANELA_DE_ATRIBUICAO = 'unificada';
const moedaDaFonte = contexto.fonte?.currency || 'BRL';

function removerToken(texto) {
  return String(texto).replace(/access_token=[^&\s"']+/g, 'access_token=[removido]');
}

function classificar(resposta) {
  if (!resposta) return { causa: 'api_recusou', detalhe: 'a Meta não respondeu' };
  if (resposta.error) {
    const detalhe = resposta.error?.message ?? String(resposta.error);
    return { causa: 'api_recusou', detalhe: removerToken(`falha de rede: ${detalhe}`).slice(0, 500) };
  }
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = Array.isArray(resposta.body) ? resposta.body[0]?.error : resposta.body?.error;
  const codigo = erro?.code;
  const detalhe = removerToken(String(erro?.message || `HTTP ${resposta.statusCode}`)).slice(0, 500);
  const limiteDeUso = resposta.statusCode === 429 || [4, 17, 32, 341, 613].includes(codigo) || (codigo >= 80000 && codigo <= 80014)
    || /SERVICE_DISABLED|accessNotConfigured|RESOURCE_EXHAUSTED|RATE_LIMIT|request limit|reduce the amount of data/i.test(JSON.stringify(erro ?? {}));
  const semAcesso = !limiteDeUso && (resposta.statusCode === 401 || resposta.statusCode === 403 || [190, 10, 200].includes(codigo));
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

function respostasDo(nome) {
  try {
    return $(nome).all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error));
  } catch (erro) {
    return [];
  }
}

const NOS_DAS_ENTIDADES = { campanhas: 'Listar campanhas', conjuntos: 'Listar conjuntos', anuncios: 'Listar anúncios' };
const NOS_DOS_RECORTES = {
  anuncio: 'Baixar anúncios',
  idade_genero: 'Baixar idade e gênero',
  posicionamento: 'Baixar posicionamento',
  regiao: 'Baixar região',
};

const respostasLidas = [
  ...Object.values(NOS_DAS_ENTIDADES).flatMap(respostasDo),
  ...Object.entries(NOS_DOS_RECORTES).filter(([chave]) => estados[chave]?.estado === 'concluido').flatMap(([, nome]) => respostasDo(nome)),
];
const requests = 4 + preparo.tentativa * 4 + respostasLidas.length;
const bytes = respostasLidas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const incompletas = [];

function dadosDe(respostas, rotulo, obrigatorio) {
  const falha = respostas.length === 0 ? { causa: 'api_recusou', detalhe: 'a Meta não respondeu' } : respostas.map(classificar).find(Boolean);
  if (falha) {
    if (obrigatorio) return { falha };
    incompletas.push(`${rotulo}: ${falha.detalhe}`);
    return { linhas: [] };
  }
  return { linhas: respostas.flatMap((resposta) => (Array.isArray(resposta.body?.data) ? resposta.body.data : [])) };
}

const estadoDoAnuncio = estados.anuncio;
if (!estadoDoAnuncio || estadoDoAnuncio.estado !== 'concluido') {
  return devolver([], [{ causa: estadoDoAnuncio?.causa ?? 'api_recusou', detalhe: estadoDoAnuncio?.detalhe ?? 'relatório de anúncios indisponível' }]);
}

const anuncios = dadosDe(respostasDo(NOS_DOS_RECORTES.anuncio), 'anúncios', true);
if (anuncios.falha) return devolver([], [anuncios.falha]);
if (anuncios.linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);

function numero(valor) {
  const convertido = typeof valor === 'string' && valor.trim() !== '' ? Number(valor) : valor;
  return typeof convertido === 'number' && Number.isFinite(convertido) ? convertido : null;
}

function somaDaLista(lista) {
  return Array.isArray(lista) ? lista.reduce((total, item) => total + (numero(item?.value) ?? 0), 0) : 0;
}

function valorDoTipo(lista, tipo) {
  const item = Array.isArray(lista) ? lista.find((acao) => acao?.action_type === tipo) : null;
  return item ? numero(item.value) ?? 0 : 0;
}

function valorDaCompra(lista) {
  return valorDoTipo(lista, 'purchase') || valorDoTipo(lista, 'offsite_conversion.fb_pixel_purchase');
}

function mediaDaLista(lista) {
  const valores = Array.isArray(lista) ? lista.map((item) => numero(item?.value)).filter((valor) => valor !== null) : [];
  return valores.length ? valores[0] : null;
}

function acoesDaLinha(linha) {
  const porChave = new Map();
  function juntar(origem, lista, campo) {
    if (!Array.isArray(lista)) return;
    for (const item of lista) {
      const tipo = typeof item?.action_type === 'string' ? item.action_type : null;
      if (!tipo) continue;
      const chave = `${origem}|${tipo}`;
      const registro = porChave.get(chave) ?? { origem, tipo, quantidade: null, valor: null, custo: null };
      registro[campo] = numero(item.value);
      porChave.set(chave, registro);
    }
  }
  juntar('acoes', linha.actions, 'quantidade');
  juntar('acoes', linha.action_values, 'valor');
  juntar('acoes', linha.cost_per_action_type, 'custo');
  juntar('conversoes', linha.conversions, 'quantidade');
  juntar('conversoes', linha.conversion_values, 'valor');
  juntar('conversoes', linha.cost_per_conversion, 'custo');
  return [...porChave.values()];
}

const linhas = [];
const campanhasPorDia = new Map();

for (const linha of anuncios.linhas) {
  const adId = String(linha.ad_id ?? '');
  const dia = linha.date_start ?? null;
  if (!adId || !dia) continue;
  const moeda = linha.account_currency ?? moedaDaFonte;
  const ids = { campaign_id: String(linha.campaign_id ?? ''), adset_id: String(linha.adset_id ?? ''), ad_id: adId, data_dia: dia };

  linhas.push({
    _tabela: 'entrega_diaria',
    ...ids,
    investimento: numero(linha.spend) ?? 0,
    impressoes: numero(linha.impressions) ?? 0,
    alcance: numero(linha.reach) ?? 0,
    frequencia: numero(linha.frequency),
    cliques: numero(linha.clicks) ?? 0,
    cliques_link: numero(linha.inline_link_clicks) ?? 0,
    cliques_unicos: numero(linha.unique_clicks) ?? 0,
    cliques_link_unicos: numero(linha.unique_inline_link_clicks) ?? 0,
    cliques_saida: somaDaLista(linha.outbound_clicks),
    engajamento_post: numero(linha.inline_post_engagement) ?? 0,
    video_reproducoes: somaDaLista(linha.video_play_actions),
    video_30s: somaDaLista(linha.video_30_sec_watched_actions),
    video_p25: somaDaLista(linha.video_p25_watched_actions),
    video_p50: somaDaLista(linha.video_p50_watched_actions),
    video_p75: somaDaLista(linha.video_p75_watched_actions),
    video_p95: somaDaLista(linha.video_p95_watched_actions),
    video_p100: somaDaLista(linha.video_p100_watched_actions),
    video_thruplay: somaDaLista(linha.video_thruplay_watched_actions),
    video_tempo_medio: mediaDaLista(linha.video_avg_time_watched_actions),
    ranking_qualidade: linha.quality_ranking ?? null,
    ranking_engajamento: linha.engagement_rate_ranking ?? null,
    ranking_conversao: linha.conversion_rate_ranking ?? null,
    moeda,
  });

  for (const acao of acoesDaLinha(linha)) {
    linhas.push({
      _tabela: 'acoes_diarias',
      ...ids,
      tipo_acao: acao.tipo,
      origem_metrica: acao.origem,
      quantidade: acao.quantidade,
      valor: acao.valor,
      custo_por_acao: acao.custo,
      janela_atribuicao: JANELA_DE_ATRIBUICAO,
      moeda,
    });
  }

  const campanhaId = ids.campaign_id;
  if (!campanhaId) continue;
  const chave = `${campanhaId}|${dia}`;
  const total = campanhasPorDia.get(chave) ?? {
    externalCampaignId: campanhaId, campaignName: linha.campaign_name ?? null, metricDate: dia,
    spend: 0, impressions: 0, clicks: 0, conversions: 0, revenue: 0, currency: moeda,
  };
  total.spend += numero(linha.spend) ?? 0;
  total.impressions += numero(linha.impressions) ?? 0;
  total.clicks += numero(linha.clicks) ?? 0;
  total.conversions += valorDaCompra(linha.actions);
  total.revenue += valorDaCompra(linha.action_values);
  campanhasPorDia.set(chave, total);
}

for (const total of campanhasPorDia.values()) {
  linhas.push({ ...total, spend: Math.round(total.spend * 100) / 100, revenue: Math.round(total.revenue * 100) / 100 });
}

function recortes(chave, tabela, camposDoRecorte) {
  if (estados[chave]?.estado !== 'concluido') {
    incompletas.push(`${chave}: ${estados[chave]?.detalhe ?? 'relatório indisponível'}`);
    return;
  }
  const dados = dadosDe(respostasDo(NOS_DOS_RECORTES[chave]), chave, false);
  for (const linha of dados.linhas) {
    const adsetId = String(linha.adset_id ?? '');
    const dia = linha.date_start ?? null;
    const dimensoes = {};
    for (const [coluna, campo] of camposDoRecorte) dimensoes[coluna] = linha[campo] ?? null;
    if (!adsetId || !dia || Object.values(dimensoes).some((valor) => valor === null)) continue;
    linhas.push({
      _tabela: tabela,
      campaign_id: String(linha.campaign_id ?? ''),
      adset_id: adsetId,
      data_dia: dia,
      ...dimensoes,
      investimento: numero(linha.spend) ?? 0,
      impressoes: numero(linha.impressions) ?? 0,
      alcance: numero(linha.reach) ?? 0,
      cliques: numero(linha.clicks) ?? 0,
      cliques_link: numero(linha.inline_link_clicks) ?? 0,
      leads: valorDoTipo(linha.actions, 'lead'),
      compras: valorDaCompra(linha.actions),
      receita_compras: valorDaCompra(linha.action_values),
      conversas_iniciadas: valorDoTipo(linha.actions, 'onsite_conversion.messaging_conversation_started_7d'),
      visualizacoes_pagina: valorDoTipo(linha.actions, 'landing_page_view'),
      moeda: linha.account_currency ?? moedaDaFonte,
    });
  }
}

recortes('idade_genero', 'recorte_idade_genero', [['idade', 'age'], ['genero', 'gender']]);
recortes('posicionamento', 'recorte_posicionamento', [['plataforma_publicacao', 'publisher_platform'], ['posicao_plataforma', 'platform_position']]);
recortes('regiao', 'recorte_regiao', [['regiao', 'region']]);

function valorMonetario(valor) {
  const convertido = numero(valor);
  return convertido !== null && convertido > 0 ? convertido / 100 : null;
}

function janelaDeAtribuicao(especificacao) {
  if (!Array.isArray(especificacao)) return null;
  const itens = especificacao.map((item) => `${item?.event_type}:${item?.window_days}`).sort();
  return itens.length ? itens.join(',') : null;
}

function entidades(chave, tabela, mapear) {
  const dados = dadosDe(respostasDo(NOS_DAS_ENTIDADES[chave]), chave, false);
  const vistos = new Set();
  for (const item of dados.linhas) {
    const id = String(item.id ?? '');
    if (!id || vistos.has(id)) continue;
    vistos.add(id);
    linhas.push({ _tabela: tabela, ...mapear(item, id) });
  }
}

entidades('campanhas', 'dim_campanha', (c, id) => ({
  campaign_id: id,
  nome: c.name ?? null,
  objetivo: c.objective ?? null,
  status: c.status ?? null,
  status_efetivo: c.effective_status ?? null,
  tipo_compra: c.buying_type ?? null,
  estrategia_lance: c.bid_strategy ?? null,
  orcamento_diario: valorMonetario(c.daily_budget),
  orcamento_vitalicio: valorMonetario(c.lifetime_budget),
  limite_gasto: valorMonetario(c.spend_cap),
  categorias_especiais: Array.isArray(c.special_ad_categories) ? [...c.special_ad_categories].sort().join(',') : null,
  inicio: c.start_time ?? null,
  fim: c.stop_time ?? null,
  criada_em: c.created_time ?? null,
}));

entidades('conjuntos', 'dim_conjunto', (c, id) => ({
  adset_id: id,
  campaign_id: c.campaign_id ?? null,
  nome: c.name ?? null,
  status: c.status ?? null,
  status_efetivo: c.effective_status ?? null,
  objetivo_otimizacao: c.optimization_goal ?? null,
  evento_cobranca: c.billing_event ?? null,
  estrategia_lance: c.bid_strategy ?? null,
  valor_lance: valorMonetario(c.bid_amount),
  orcamento_diario: valorMonetario(c.daily_budget),
  orcamento_vitalicio: valorMonetario(c.lifetime_budget),
  tipo_destino: c.destination_type ?? null,
  evento_conversao: c.promoted_object?.custom_event_type ?? null,
  janela_atribuicao: janelaDeAtribuicao(c.attribution_spec),
  inicio: c.start_time ?? null,
  fim: c.end_time ?? null,
  criado_em: c.created_time ?? null,
}));

entidades('anuncios', 'dim_anuncio', (a, id) => ({
  ad_id: id,
  campaign_id: a.campaign_id ?? null,
  adset_id: a.adset_id ?? null,
  nome: a.name ?? null,
  status: a.status ?? null,
  status_efetivo: a.effective_status ?? null,
  creative_id: a.creative?.id ?? null,
  criado_em: a.created_time ?? null,
}));

const saida = linhas.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi }));
const falhas = incompletas.length
  ? [{ causa: 'coleta_incompleta', detalhe: `recortes ou dimensões indisponíveis: ${incompletas.join('; ')}`.slice(0, 500) }]
  : [];
return devolver(saida, falhas);
